  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://store.anycubic.com/pages/affiliate-program', 'official_site', 'affiliate', 'Anycubic''s own affiliate page (fetched) offers a minimum of 5% commission on every qualifying order, monthly bonuses and exclusive rate increases for top performers, a 60-day cookie window, free joining and approval usually within 2-3 business days; it explicitly invites makers, 3D printing fans and content creators, and publishes the program contact taylorwang@anycubic.com. The page makes no statement about a cap on total earnings, so the cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/advertiser-terms/129417?setLocale=en_GB', 'affiliate_network', 'affiliate', 'Awin hosts live program terms for ''Anycubic (US)'', confirming a network route alongside the brand''s own page. Lasso''s listing for the company shows 4% with a 30-day cookie, which conflicts with the brand''s own published minimum of 5% and 60-day cookie, so the brand''s official figures are recorded. No creator-count figure is published anywhere fetched, so saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 16, 11, 12, 9, 4, '{"niche_fit": "Desktop 3D printers are a staple of maker and tech creator content \u2014 unboxings, print tests, reviews and project builds.", "ugc_evidence": "The brand''s own program page targets content creators directly, and the brand runs UGC campaigns such as the AnycubicMaker Challenge across Instagram, TikTok and YouTube.", "compensation": "Minimum 5% commission with monthly bonuses and rate increases for top performers and a 60-day cookie, per the brand''s own page; no cap statement is published, so the cap stays unknown.", "contact_access": "A named program email, taylorwang@anycubic.com, is published on the brand''s own affiliate page alongside the application.", "opportunity_availability": "Free, open application on the brand''s own page with approval typically in 2-3 business days; a US program also runs on Awin.", "credibility": "Major global desktop 3D printing brand founded in Shenzhen in 2015, selling in over 200 countries."}'::jsonb);
