  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://goifetch.com/pages/affiliate-program', 'official_site', 'affiliate', 'iFetch''s own affiliate page (fetched) states affiliates earn 8% on all iFetch products sold with their code except the iFetch Too, which pays 4%; the program runs on the Refersion platform with signup at goifetch.refersion.com, pays monthly via PayPal or check, is open to US-based affiliates, prefers 10K+ followers but considers smaller creators, and asks affiliates to post at least 3 videos with their code per year. The page publishes the contact info@goifetch.com. It makes no statement about a cap on total earnings, so the cap is recorded as unknown, and no creator count is published, so saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 17, 12, 12, 7, 3, '{"niche_fit": "Automatic ball launchers and enrichment toys are highly demonstrable dog products, ideal for pet creator video content.", "ugc_evidence": "The brand''s own program is built around affiliate photos and videos \u2014 affiliates must post at least 3 videos a year \u2014 and smaller creators under 10K followers are still considered.", "compensation": "8% per sale on most products (4% on the iFetch Too) per the brand''s own page, on products priced $49.99-$229.99; no cap statement is published, so the cap stays unknown.", "contact_access": "The brand publishes its contact email, info@goifetch.com, and phone on its own affiliate page alongside the application.", "opportunity_availability": "Open application through Refersion, but US-based affiliates only and 10K+ followers preferred, which narrows availability.", "credibility": "Small family-run Austin company launched via Kickstarter, with its own e-commerce and a long product history."}'::jsonb);
